 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    # The objects are solid monochrome 3x3 squares; project their middle
    # row and middle column across the whole grid.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                centers.append((r + 1, c + 1, color))
    rays = {}
    for cr, cc, color in centers:
        for c in range(w):
            rays.setdefault((cr, c), set()).add(color)
        for r in range(h):
            rays.setdefault((r, cc), set()).add(color)
    for (r, c), colors in rays.items():
        if grid[r][c] != 0:
            continue
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
